import React from 'react';
import { Container, Typography, Box, Button } from '@material-ui/core';
import { makeStyles } from '@material-ui/core/styles';
import { Link } from 'react-router-dom';

const useStyles = makeStyles((theme) => ({
  root: {
    minHeight: '100vh',
    paddingTop: theme.spacing(8),
    paddingBottom: theme.spacing(8),
    textAlign: 'center',
    background: 'linear-gradient(120deg, #a1c4fd 0%, #c2e9fb 100%)',
    position: 'relative',
    overflow: 'hidden',
  },
  content: {
    position: 'relative',
    zIndex: 2,
    animation: '$fadeIn 1s ease-out',
    backdropFilter: 'blur(5px)',
    padding: theme.spacing(6),
    borderRadius: 20,
    background: 'rgba(255, 255, 255, 0.1)',
  },
  title: {
    marginBottom: theme.spacing(4),
    fontWeight: 900,
    fontSize: '4rem',
    background: 'linear-gradient(45deg, #667eea 0%, #764ba2 100%)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    textShadow: '3px 3px 6px rgba(0,0,0,0.2)',
    animation: '$slideUp 1s ease-out',
    letterSpacing: '2px',
  },
  subtitle: {
    marginBottom: theme.spacing(6),
    color: '#4a4a4a',
    fontSize: '1.8rem',
    lineHeight: 1.8,
    fontWeight: 500,
    animation: '$slideUp 1s ease-out 0.3s',
    opacity: 0,
    animationFillMode: 'forwards',
    textShadow: '1px 1px 2px rgba(0,0,0,0.1)',
  },
  loginButton: {
    marginTop: theme.spacing(4),
    padding: theme.spacing(2.5, 8),
    fontSize: '1.4rem',
    borderRadius: 50,
    background: 'linear-gradient(45deg, #667eea 0%, #764ba2 100%)',
    boxShadow: '0 4px 20px rgba(102, 126, 234, 0.4)',
    transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
    animation: '$slideUp 1s ease-out 0.6s',
    opacity: 0,
    animationFillMode: 'forwards',
    '&:hover': {
      transform: 'translateY(-5px) scale(1.05)',
      boxShadow: '0 6px 30px rgba(102, 126, 234, 0.6)',
    },
  },
  decorCircle: {
    position: 'absolute',
    borderRadius: '50%',
    background: 'linear-gradient(45deg, #667eea 30%, #764ba2 90%)',
    opacity: 0.15,
    animation: '$float 8s ease-in-out infinite',
    filter: 'blur(3px)',
  },
  '@keyframes fadeIn': {
    from: { opacity: 0 },
    to: { opacity: 1 },
  },
  '@keyframes slideUp': {
    from: {
      opacity: 0,
      transform: 'translateY(30px)',
    },
    to: {
      opacity: 1,
      transform: 'translateY(0)',
    },
  },
  '@keyframes float': {
    '0%, 100%': {
      transform: 'translateY(0) rotate(0deg) scale(1)',
    },
    '50%': {
      transform: 'translateY(-30px) rotate(15deg) scale(1.1)',
    },
  },
}));

function Home() {
  const classes = useStyles();

  return (
    <Container className={classes.root} maxWidth={false}>
      {[...Array(8)].map((_, i) => (
        <Box
          key={i}
          className={classes.decorCircle}
          style={{
            width: `${Math.random() * 300 + 100}px`,
            height: `${Math.random() * 300 + 100}px`,
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
            animationDelay: `${Math.random() * 5}s`,
            animationDuration: `${Math.random() * 5 + 5}s`,
          }}
        />
      ))}

      <Box className={classes.content} maxWidth={1000} mx="auto">
        <Typography variant="h1" className={classes.title}>
          Welcome to Dynonary English
        </Typography>

        <Typography variant="h4" className={classes.subtitle}>
          Your personal English learning companion. Improve your vocabulary, practice pronunciation, 
          and master the English language with our interactive tools.
        </Typography>

        <Button
          component={Link}
          to="/login"
          variant="contained"
          color="primary"
          size="large"
          className={classes.loginButton}
        >
          Start Your Journey
        </Button>
      </Box>
    </Container>
  );
}

export default Home;
